import React, { useRef, useState, useEffect } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {
  const scannerRef = useRef(null);
  const beepRef = useRef(null);

  const [isScanning, setIsScanning] = useState(false);
  const [student, setStudent] = useState(null);
  const [message, setMessage] = useState("");
  const [history, setHistory] = useState([]);

  useEffect(() => {
    beepRef.current = new Audio(
      "https://www.soundjay.com/button/sounds/beep-01a.mp3"
    );
  }, []);

  const startScanner = async () => {
    try {
      if (!scannerRef.current) {
        scannerRef.current = new Html5Qrcode("reader");
      }

      await scannerRef.current.start(
        { facingMode: "environment" },
        { fps: 20, qrbox: 250 },
        async (decodedText) => {
          await stopScanner();
          beepRef.current?.play().catch(() => {});
          handleScan(decodedText);
        }
      );

      setIsScanning(true);
      setStudent(null);
      setMessage("");
    } catch (err) {
      console.error(err);
    }
  };

  const stopScanner = async () => {
    if (scannerRef.current) {
      try {
        await scannerRef.current.stop();
      } catch {}
      setIsScanning(false);
    }
  };

  const handleScan = async (qrData) => {
    try {
      const res = await fetch("http://localhost:5000/scan-qr", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ qrData }),
      });

      const data = await res.json();
      const time = new Date().toLocaleTimeString();

      if (data.success) {
        setStudent(data.user);
        setMessage("✅ Attendance Marked");

        setHistory((prev) => [
          { name: data.user.name, time },
          ...prev,
        ]);
      } else {
        setMessage(data.message || "Error ❌");
      }
    } catch {
      setMessage("Server Error ❌");
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <h1>📷 QR Scanner</h1>

        {!isScanning ? (
          <button style={styles.startBtn} onClick={startScanner}>
            Start Scan
          </button>
        ) : (
          <button style={styles.stopBtn} onClick={stopScanner}>
            Stop
          </button>
        )}

        <div id="reader" style={{ width: "100%", marginTop: 20 }}></div>

        {student && (
          <div style={styles.result}>
            <h2>{student.name}</h2>
            <p>{student.college_name}</p>
            <h3>{message}</h3>
          </div>
        )}

        <div style={styles.history}>
          <h3>History</h3>
          {history.length === 0 ? (
            <p>No records</p>
          ) : (
            history.map((h, i) => (
              <div key={i}>
                {h.name} - {h.time}
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

export default QRScanner;

const styles = {
  page: {
    height: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "#1e1e2f",
    color: "#fff",
  },
  card: {
    padding: 20,
    borderRadius: 10,
    background: "#2c2c3e",
    width: 350,
    textAlign: "center",
  },
  startBtn: {
    padding: 10,
    background: "#00c6ff",
    border: "none",
    color: "#fff",
    cursor: "pointer",
  },
  stopBtn: {
    padding: 10,
    background: "#ff4b2b",
    border: "none",
    color: "#fff",
    cursor: "pointer",
  },
  result: {
    marginTop: 10,
  },
  history: {
    marginTop: 15,
    textAlign: "left",
  },
};
